INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31411, 'Matthew 11:28', 'Matthew', 11, 28, 'ای تاسو ټول چې د خپلو درنو بارونو څخه ستړي شوي یئ، ماته راشئ او زه به ارام درکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_28.mp3', '', 1761754199, 1761754199),
(31412, 'Matthew 11:29', 'Matthew', 11, 29, 'زما جغ په خپله غاړه کېږدئ او زما څخه یې زده کړئ، ځکه چې زه په زړه نرم او عاجز یم او ستاسو زړونه به ارام ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_29.mp3', '', 1761754199, 1761754199),
(31413, 'Matthew 11:30', 'Matthew', 11, 30, 'ځکه چې زما د جغ وړل اسانه او بار مې سپک دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_30.mp3', '', 1761754199, 1761754199),
(31414, 'Luke 7:1', 'Luke', 7, 1, 'کله چې عیسی خلکو ته خپلې ټولې خبرې وکړې، نو کپرناحوم ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_1.mp3', '', 1761754199, 1761754199),
(31415, 'Luke 7:2', 'Luke', 7, 2, 'هلته یو رومي منصبدار ؤ او یو نوکر یې درلود چې په هغه ډېر ګران ؤ. هغه نوکر ناروغ ؤ او مرګ ته نژدې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_2.mp3', '', 1761754199, 1761754199),
(31416, 'Luke 7:3', 'Luke', 7, 3, 'کله چې هغه منصبدار د عیسی په هکله واورېدل، نو یو څو یهودي مشران یې ورولېږل، ترڅو د هغه څخه وغواړي چې راشي او نوکر یې روغ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_3.mp3', '', 1761754199, 1761754199),
(31417, 'Luke 7:4', 'Luke', 7, 4, 'هغوی عیسی ته راغلل او سختې زارۍ یې ورته وکړې او ورته ویې ویل: «دا سړی په رښتیا د دې وړ دی چې مرسته ورسره وکړې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_4.mp3', '', 1761754199, 1761754199),
(31418, 'Luke 7:5', 'Luke', 7, 5, 'ځکه چې هغه زمونږ د خلکو سره مینه لري او مونږ ته یې کنیسه هم جوړه کړې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_5.mp3', '', 1761754199, 1761754199),
(31419, 'Luke 7:6', 'Luke', 7, 6, 'نو عیسی د هغوی سره لاړ. خو کله چې د هغه کور ته نژدې شو، نو هغه منصبدار خپل څو ملګري ورولېږل چې هغه ته ووایي: «ښاغلیه! خپل ځان دې مه په تکلیفوه، زه د دې لایق نه یم چې زما کور ته راشې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_6.mp3', '', 1761754199, 1761754199),
(31420, 'Luke 7:7', 'Luke', 7, 7, 'او دا مې هم غوره ونه ګڼله چې خپله تاسو ته راشم. ته یوازې حکم وکړه، نو زما نوکر به روغ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_7.mp3', '', 1761754199, 1761754199),
(31421, 'Luke 7:8', 'Luke', 7, 8, 'ځکه چې زه هم د بل د امر لاندې یم او عسکر زما د امر لاندې دي. کله چې کوم یو ته ووایم چې لاړ شه، نو هغه ځي او بل ته ووایم راشه، نو راځي او خپل نوکر ته ووایم چې دا کار وکړه، نو هغه یې کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_8.mp3', '', 1761754199, 1761754199),
(31422, 'Luke 7:9', 'Luke', 7, 9, 'کله چې عیسی دا واورېدل، نو حیران شو او خلکو ته یې چې ورپسې روان وو، مخ راواړاوه او ویې ویل: «زه تاسو ته وایم چې ما په اسراییلو کې هم داسې ایمان نه دی لیدلی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_9.mp3', '', 1761754199, 1761754199),
(31423, 'Luke 7:10', 'Luke', 7, 10, 'کله چې لېږل شوي کسان بېرته کور ته راستانه شول، نو هغه نوکر یې روغ رمټ ولیده. عیسی د یوې کونډې زوی راژوندی کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_10.mp3', '', 1761754199, 1761754199),
(31424, 'Luke 7:11', 'Luke', 7, 11, 'بله ورځ عیسی د خپلو شاګردانو او د خلکو د یوې لویې ډلې سره نایین نومي ښار ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_11.mp3', '', 1761754199, 1761754199),
(31425, 'Luke 7:12', 'Luke', 7, 12, 'کله چې د ښار دروازې ته نژدې شو، نو یوه جنازه یې ولیدله چې راووتله. دا مړی د یوې کونډې ښځې ‎یوازېنی زوی ؤ او د هغې سره د ښار ګڼ شمېر خلک ملګري وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_12.mp3', '', 1761754199, 1761754199),
(31426, 'Luke 7:13', 'Luke', 7, 13, 'کله چې عیسی هغه ښځه ولیدله، نو زړه یې ورباندې وسوځېده او ورته ویې ویل: «نوره مه ژاړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_13.mp3', '', 1761754199, 1761754199),
(31427, 'Luke 7:14', 'Luke', 7, 14, 'بیا هغه وروړاندې شو او په تابوت باندې یې لاس کېښود او کومو خلکو چې تابوت وړلو، ودرېدل. عیسی وویل: «ای ځوانه! تاته وایم راپاڅېږه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_14.mp3', '', 1761754199, 1761754199),
(31428, 'Luke 7:15', 'Luke', 7, 15, 'هغه مړی کښېناست او په خبرو یې پیل وکړ او عیسی هغه بېرته خپلې مور ته وسپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_15.mp3', '', 1761754199, 1761754199),
(31429, 'Luke 7:16', 'Luke', 7, 16, 'هغوی ټول وېرې واخیستل او د خدای ثنا یې وویله او ویې ویل: «په مونږ کې یو لوی پیغمبر پیدا شوی دی. خدای راغلی چې د خپل قوم سره مرسته وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_16.mp3', '', 1761754199, 1761754199),
(31430, 'Luke 7:17', 'Luke', 7, 17, 'عیسی چې څه کړي وو د هغو خبر په ټولې یهودیې او شاوخوا سیمو کې خپور شو. د عیسی په هکله د یحیی پوښتنه (متي ۱۱‏:‌۲‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_17.mp3', '', 1761754199, 1761754199),
(31431, 'Luke 7:18', 'Luke', 7, 18, 'د یحیی شاګردانو هغه د دې ټولو کارونو څخه خبر کړ. نو یحیی د هغوی څخه دوه تنه راوغوښتل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_18.mp3', '', 1761754199, 1761754199),
(31432, 'Luke 7:19', 'Luke', 7, 19, 'او هغوی یې عیسی ته ورولېږل چې پوښتنه ورڅخه وکړي: «ایا ته هغه څوک یې چې ویل شوي وو باید راغلی وای، یا د کوم بل چا په تمه واوسو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_19.mp3', '', 1761754199, 1761754199),
(31433, 'Luke 7:20', 'Luke', 7, 20, 'کله چې هغوی عیسی ته ورغلل، ورته ویې ویل: «مونږ تعمید ورکوونکي یحیی تاته رالېږلي یو چې پوښتنه وکړو چې ته هغه څوک یې چې باید راغلی وای یا د کوم بل چا په تمه واوسو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_20.mp3', '', 1761754199, 1761754199),
(31434, 'Luke 7:21', 'Luke', 7, 21, 'په هماغه ساعت عیسی ډېر خلک د ډول ډول ناروغیو، طاعون او پېریانو څخه روغ کړل او ډېر ړانده یې بینا کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_21.mp3', '', 1761754199, 1761754199),
(31435, 'Luke 7:22', 'Luke', 7, 22, 'هغه د یحیی استازو ته په ځواب کې وویل: «بېرته لاړ شئ او څه مو چې لیدلي او اورېدلي، هغه یحیی ته ووایئ چې څنګه ړانده بینا کیږي، ګوډان کولای شي وګرځي، کوم خلک چې په جذام باندې اخته وو هغه پاک او روغ شوي دي او کاڼه اوري، مړي راژوندي کیږي او غریبانو ته زېری ورکول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_22.mp3', '', 1761754199, 1761754199),
(31436, 'Luke 7:23', 'Luke', 7, 23, 'بختور دی هغه څوک چې په ما شک ونه کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_23.mp3', '', 1761754199, 1761754199),
(31437, 'Luke 7:24', 'Luke', 7, 24, 'کله چې د یحیی استازي لاړل، نو عیسی د یحیی په هکله د خلکو سره خبرې پیل کړې او ویې ویل: «تاسو د څه شي د لیدلو دپاره دښتې ته تللي وئ؟ ایا د هغې لوخې د لیدلو دپاره چې باد یې خوځوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_24.mp3', '', 1761754199, 1761754199),
(31438, 'Luke 7:25', 'Luke', 7, 25, 'نو بیا د څه شي د لیدلو دپاره تللي وئ؟ ایا د هغه چا د لیدلو دپاره چې ښکلي کالي یې اغوستي وو؟ ګورئ، کوم خلک چې قیمتي کالي اغوندي، هغوی په عیش او عشرت کې ژوند تېروي او په ماڼیو کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_25.mp3', '', 1761754199, 1761754199),
(31439, 'Luke 7:26', 'Luke', 7, 26, 'نو بیا د څه شي د لیدلو دپاره وتلي وئ؟ ایا د یو پیغمبر د لیدلو دپاره؟ هو، زه تاسو ته وایم چې هغه د یو پیغمبر نه هم ډېر لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_26.mp3', '', 1761754199, 1761754199),
(31440, 'Luke 7:27', 'Luke', 7, 27, 'دا هغه څوک دی چې د هغه په هکله د خدای په کلام کې لیکل شوي دي: ګورئ، زه به خپل استازی ستا څخه مخکې ولېږم چې ستا دپاره لاره تیاره کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_27.mp3', '', 1761754199, 1761754199),
(31441, 'Luke 7:28', 'Luke', 7, 28, 'عیسی زیاته کړه: «زه تاسو ته وایم چې په دې نړۍ کې د یحیی څخه بل څوک لوی نه دی زېږول شوی، خو بیاهم د خدای په پاچاهۍ کې تر ټولو کوچنی د هغه نه لوی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_28.mp3', '', 1761754199, 1761754199),
(31442, 'Luke 7:29', 'Luke', 7, 29, 'کله چې ټولو خلکو او حتی مالیه ټولوونکو د عیسی خبرې واورېدلې، نو په دې یې اقرار وکړ چې د خدای لاره سمه ده، ځکه چې هغوی د یحیی په لاس د تعمید غسل اخیستی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_29.mp3', '', 1761754199, 1761754199),
(31443, 'Luke 7:30', 'Luke', 7, 30, 'خو فریسیانو او د شریعت عالمانو د خدای هغه مقصد چې د هغوی دپاره یې درلود رد کړ، ځکه چې هغوی د یحیی په لاس د تعمید غسل نه ؤ اخیستی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_30.mp3', '', 1761754199, 1761754199),
(31444, 'Luke 7:31', 'Luke', 7, 31, 'عیسی وویل: «د دې زمانې خلک د څه شي سره پرتله کړم؟ دا څه ډول خلک دي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_31.mp3', '', 1761754199, 1761754199),
(31445, 'Luke 7:32', 'Luke', 7, 32, 'دوی د هغو ماشومانو په شان دي چې په بازار کې ناست وي او یو بل ته چیغې وهي او وایي: ‹مونږ تاسو ته شپیلۍ ووهله، خو تاسو ګډا ونه کړه. مونږ درته د غم سندرې وویلې، خو تاسو ونه ژړل.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_32.mp3', '', 1761754199, 1761754199),
(31446, 'Luke 7:33', 'Luke', 7, 33, 'ځکه کله چې تعمید ورکوونکی یحیی راغی هغه به نه ډوډۍ خوړله او نه یې شراب څښل، نو تاسو به ویل چې هغه پېریانو نیولی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_33.mp3', '', 1761754199, 1761754199),
(31447, 'Luke 7:34', 'Luke', 7, 34, 'د انسان زوی راغی چې هم خوري او هم څښي نو تاسو وایئ چې دې سړي ته وګورئ، هغه خېټور، شرابي او د مالیه ټولوونکو او ګناهکارانو ملګری دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_34.mp3', '', 1761754199, 1761754199),
(31448, 'Luke 7:35', 'Luke', 7, 35, 'خو بیاهم د خدای حکمت د هغو خلکو په وسیله چې هغه یې منلی دی، رښتینی ثابت شو.» عیسی د فریسي شمعون په کور کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_35.mp3', '', 1761754199, 1761754199),
(31449, 'Luke 7:36', 'Luke', 7, 36, 'یو فریسي عیسی ته بلنه ورکړه چې د هغه سره ډوډۍ وخوري، نو عیسی د هغه کور ته ورغی او د هغه سره دسترخوان ته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_36.mp3', '', 1761754199, 1761754199),
(31450, 'Luke 7:37', 'Luke', 7, 37, 'په هغه ښار کې یوه بدکاره ښځه اوسېدله. هغه خبره شوه چې عیسی د هغه فریسي په کور کې ډوډۍ خوري، نو د عطرو څخه ډک د مرمرو د بوتل سره راغله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_37.mp3', '', 1761754199, 1761754199),
(31451, 'Luke 7:38', 'Luke', 7, 38, 'هغه ښځه د عیسی شاته د هغه د پښو سره ودرېدله او ژړل یې. د هغې اوښکې د عیسی په پښو باندې تویې شوې او هغه لمدې شوې. ښځې هغه په خپلو ویښتانو باندې وچې کړلې، د هغه پښې یې ښکل کړې او عطر یې ورباندې واچول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_38.mp3', '', 1761754199, 1761754199),
(31452, 'Luke 7:39', 'Luke', 7, 39, 'کله چې هغه فریسي چې عیسی یې مېلمه کړی ؤ دا ولیدل، نو د خپل ځان سره یې وویل: «که چېرې دا سړی په رښتیا پیغمبر وای نو هغه باید په دې پوه شوی وای چې دا ښځه چې هغه ته لاس وروړي، څوک ده او څنګه ښځه ده. هغه یوه ګناهکاره ښځه ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_39.mp3', '', 1761754199, 1761754199),
(31453, 'Luke 7:40', 'Luke', 7, 40, 'نو عیسی هغه فریسي ته وویل: «ای شمعونه! زه غواړم تاته یو څه ووایم.» هغه وویل: «ښه استاذه! ووایه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_40.mp3', '', 1761754199, 1761754199),
(31454, 'Luke 7:41', 'Luke', 7, 41, 'عیسی وویل: «دوه کسانو د یو چا څخه پور اخیستی ؤ، د هغو څخه یو یې پنځه سوه د سپینو زرو سکې پوروړی ؤ او بل یې پنځوس سکې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_41.mp3', '', 1761754199, 1761754199),
(31455, 'Luke 7:42', 'Luke', 7, 42, 'هغوی دواړو هېڅ نه لرل چې خپل پور ورکړي، نو پور ورکوونکي هغو دواړو ته خپل پورونه وروبخښل. نو اوس په دې دواړو کې به کوم یو د هغه سره زیاته مینه وکړي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_42.mp3', '', 1761754199, 1761754199),
(31456, 'Luke 7:43', 'Luke', 7, 43, 'شمعون په ځواب کې وویل: «زما په خیال کوم سړي ته چې زیات پور وبخښل شو.» عیسی وویل: «تا سم قضاوت وکړ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_43.mp3', '', 1761754199, 1761754199),
(31457, 'Luke 7:44', 'Luke', 7, 44, 'بیا یې ښځې ته مخ راواړاوه او شمعون ته یې وویل: «دا ښځه وینې؟ زه ستا کور ته راغلم خو تا زما د پښو دپاره اوبه رانه وړلې، خو هغې په خپلو اوښکو باندې زما پښې ووینځلې او په خپلو ویښتانو یې وچې کړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_44.mp3', '', 1761754199, 1761754199),
(31458, 'Luke 7:45', 'Luke', 7, 45, 'تا زه ښکل نه کړم، خو د کوم وخت نه چې زه دلته راغلی یم دا ښځه لګیا ده زما پښې ښکلوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke7_verse_45.mp3', '', 1761754199, 1761754199),
