(31506, 'Luke 18:43', 'Luke', 18, 43, 'او هغه سمدلاسه بینا شو او په داسې حال کې چې د خدای ثنا یې ویله، د عیسی پسې روان شو. کله چې خلکو دا هرڅه ولیدل، نو ټولو د خدای ثنا وویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke18_verse_43.mp3', '', 1761754199, 1761754199),
(31507, 'Philemon 1:1', 'Philemon', 1, 1, 'دا لیک د پولوس له خوا چې د عیسی مسیح په خاطر زنداني دی او زمونږ د ورور تیموتاوس له خوا خپل ګران او د خدمت ملګري فیلیمون ته', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_1.mp3', '', 1761754199, 1761754199),
(31508, 'Philemon 1:2', 'Philemon', 1, 2, 'او خپلې خور اپفیې او ارخیپوس ته چې لکه د یو عسکر په شان زما همکار دی او ستاسو د کور کلیسا ته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_2.mp3', '', 1761754199, 1761754199),
(31509, 'Philemon 1:3', 'Philemon', 1, 3, 'زمونږ د پلار خدای او څښتن عیسی مسیح فضل او سلامتي دې وي په تاسو باندې. د فیلیمون مینه او ایمان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/philemon1_verse_3.mp3', '', 1761754199, 1761754199),
